<?php /** @var array $ev, $bars, $orders, $kpi, $sel */ ?>
<div class="page-head"><div><p class="muted" style="margin-top:0">Les festivaliers commandent au bar depuis leur carte cashless, paient avec leur solde, et récupèrent au comptoir quand leur numéro s'affiche sur l'écran d'appel. Plus de file d'attente à la commande.</p></div></div>
<form method="post" class="card stack"><?= csrf_field() ?>
  <label class="switch"><input type="checkbox" name="click_collect" value="1" <?= (int)$ev['click_collect'] ? 'checked' : '' ?>><span></span> Activer la commande à distance</label>
  <?php if (!(int)$ev['cashless_enabled']): ?><p class="flash warning">Le cashless n'est pas activé sur cet événement : le click & collect paie avec le solde de la carte.</p><?php endif; ?>
  <div class="field mb0"><label>Bars qui prennent les commandes</label><div class="row" style="gap:12px;flex-wrap:wrap"><?php foreach ($bars as $b): ?><label class="check"><input type="checkbox" name="bars[]" value="<?= (int)$b['id'] ?>" <?= !$sel || in_array((int)$b['id'], $sel, true) ? 'checked' : '' ?>> <?= e($b['name']) ?></label><?php endforeach; ?><?php if (!$bars): ?><span class="muted">Crée d'abord un bar dans Entrevo Pay.</span><?php endif; ?></div></div>
  <div><button class="btn">Enregistrer</button></div>
</form>
<div class="kpis mt"><div class="kpi"><small>Commandes</small><b><?= (int)$kpi['n'] ?></b></div><div class="kpi"><small>Montant</small><b><?= e(money((int)$kpi['total'])) ?></b></div><div class="kpi"><small>En préparation</small><b><?= (int)$kpi['waiting'] ?></b></div><div class="kpi"><small>Préparation moyenne</small><b><?= $kpi['prep'] ? e(Staff::hm((int)round($kpi['prep'] / 60))) : '—' ?></b></div></div>
<div class="card table-card mt"><div class="card-head"><h2>Dernières commandes</h2><span class="grow"></span><small class="muted">Elles arrivent sur l'écran de préparation des caisses du bar</small></div>
<?php if (!$orders): ?><p class="muted" style="padding:0 20px 20px">Aucune commande pour l'instant.</p><?php else: ?><table class="table"><thead><tr><th>N°</th><th>Bar</th><th>Articles</th><th class="num">Montant</th><th>État</th><th>Heure</th></tr></thead><tbody>
<?php foreach ($orders as $o): ?><tr><td><b><?= (int)$o['order_no'] ?></b></td><td><?= e($o['bar']) ?></td><td><small><?= e(implode(', ', array_map(fn($l) => $l['qty'] . ' × ' . $l['name'], json_decode((string)$o['items'], true) ?: []))) ?></small></td><td class="num"><?= e(money((int)$o['amount'])) ?></td>
<td><?= ['new' => '<span class="badge">En préparation</span>', 'ready' => '<span class="badge ok">Prête</span>', 'served' => '<span class="badge">Récupérée</span>'][$o['prep_status']] ?? '' ?></td><td><?= e(date('H:i', strtotime($o['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
